BEGIN;
CREATE OR REPLACE FUNCTION fn_validate_care_follow_up() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE mc bigint; sc bigint; cp bigint; c bigint; a bigint; BEGIN IF NEW.meeting_id IS NOT NULL THEN SELECT client_id,advisor_id,care_plan_id,money_case_id,safety_case_id INTO c,a,cp,mc,sc FROM client_care_meetings WHERE id=NEW.meeting_id; IF NOT FOUND THEN RAISE EXCEPTION 'Meeting neexistuje' USING ERRCODE='23503'; END IF; IF c<>NEW.client_id OR a<>NEW.advisor_id THEN RAISE EXCEPTION 'Follow-up neodpovida klientovi/advisorovi meetingu' USING ERRCODE='23514'; END IF; IF NEW.care_plan_id IS NOT NULL AND NEW.care_plan_id IS DISTINCT FROM cp THEN RAISE EXCEPTION 'Jiny care plan' USING ERRCODE='23514'; END IF; IF NEW.money_case_id IS NOT NULL AND NEW.money_case_id IS DISTINCT FROM mc THEN RAISE EXCEPTION 'Jiny MONEY case nez meeting' USING ERRCODE='23514'; END IF; IF NEW.safety_case_id IS NOT NULL AND NEW.safety_case_id IS DISTINCT FROM sc THEN RAISE EXCEPTION 'Jiny SAFETY case nez meeting' USING ERRCODE='23514'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER trg_validate_care_follow_up BEFORE INSERT OR UPDATE ON client_care_follow_ups FOR EACH ROW EXECUTE FUNCTION fn_validate_care_follow_up();
COMMIT;
